#include "../cuda/kag_adapter_v4.cuh"
#include "../../cuda-engine/include/runtime.cuh"
#include "feature_hash.hpp"
#include <cuda_runtime.h>
#include <cstdlib>
#include <iostream>
#include <vector>
using namespace kagcuda;struct Snap4{uint64_t hash;int32_t raw[bonsaikg_test::TARGETED_FEATURE_COUNT];};
__device__ inline Action scripted4(const Sim&sim,int p){Action a{};a.n_units=sim.st.farms[p].n_units;const int s=sim.st.step;if(s==0){a.n_orders=4;a.orders[0]={M_BUY_SEED,WHEAT,3};a.orders[1]={M_BUY_PRODUCT,WHEAT,2};a.orders[2]={M_BUY_PRODUCT,FERTILIZER,1};a.orders[3]={M_HIRE,0,1};}else if(s==1)a.units[0]={OP_PICKUP,WHEAT,1};else if(s==2)a.units[0]={OP_PLANT,WHEAT,1};else if(s==3)a.units[0]={OP_WATER,0,1};else if(s==4){a.units[0]={OP_PICKUP,FERTILIZER,1};a.n_orders=1;a.orders[0]={M_BUY_ANIMAL,GOOSE,1};}else if(s==5)a.units[0]={OP_FERTILIZE,0,1};else if(s==6)a.units[0]={OP_PICKUP,GOOSE,1};else if(s==7)a.units[0]={OP_WEST,0,1};else if(s==8)a.units[0]={OP_BUILD_COOP,0,1};else if(s==9)a.units[0]={OP_PLACE,GOOSE,1};else if(s==10)a.units[0]={OP_CARE,0,1};else if(s==11)a.units[0]={OP_FEED,0,1};return a;}
__global__ void init4f(Config cfg,DeviceTables tab,Sim*sim){if(!blockIdx.x&&!threadIdx.x)sim->init(cfg,&tab);}__global__ void step4f(Sim*sim,Snap4*out,int active,int observe){if(blockIdx.x||threadIdx.x||sim->st.done)return;bonsaikg4::CudaObservation4 obs(make_observation(*sim,observe));auto&z=out[sim->st.step];z.hash=bonsaikg_test::hash_feature_registry(obs);bonsaikg_test::targeted_features(obs,z.raw);Action a0{},a1{};a0.n_units=sim->st.farms[0].n_units;a1.n_units=sim->st.farms[1].n_units;if(active==0)a0=scripted4(*sim,0);else a1=scripted4(*sim,1);sim->step_with_unit_counts(a0,sim->st.farms[0].n_units,a1,sim->st.farms[1].n_units);}
int main(int argc,char**argv){configure_device();TablesOwner tables;const uint64_t seed=argc>1?std::strtoull(argv[1],nullptr,10):12345ull;const int steps=argc>2?std::atoi(argv[2]):80;const int active=argc>3?std::atoi(argv[3]):0;const int observe=argc>4?std::atoi(argv[4]):0;Config cfg;cfg.seed=seed;cfg.episode_steps=steps;Sim*sim=nullptr;Snap4*d=nullptr;KAGCUDA_CHECK(cudaMalloc((void**)&sim,sizeof(Sim)));KAGCUDA_CHECK(cudaMalloc((void**)&d,steps*sizeof(Snap4)));init4f<<<1,1>>>(cfg,tables.dev,sim);KAGCUDA_CHECK(cudaDeviceSynchronize());for(int i=0;i<steps-1;++i){step4f<<<1,1>>>(sim,d,active,observe);KAGCUDA_CHECK(cudaDeviceSynchronize());}std::vector<Snap4>h(steps-1);KAGCUDA_CHECK(cudaMemcpy(h.data(),d,h.size()*sizeof(Snap4),cudaMemcpyDeviceToHost));for(size_t t=0;t<h.size();++t){std::cout<<"T="<<t<<" H="<<h[t].hash<<" R=";for(int i=0;i<bonsaikg_test::TARGETED_FEATURE_COUNT;++i){if(i)std::cout<<',';std::cout<<h[t].raw[i];}std::cout<<"\n";}cudaFree(sim);cudaFree(d);return 0;}
